import React from 'react';
import ProductsGrid from './Products/ProductsGrid';
import { Plus, Filter } from 'lucide-react';

const ProductsPage = () => {
  return (
    <>
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-neutral-900 dark:text-white">Gestion des produits</h1>
          <p className="text-neutral-600 dark:text-neutral-400">Gérez votre catalogue de produits</p>
        </div>
        <div className="flex space-x-3">
          <button className="flex items-center space-x-2 px-4 py-2.5 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white/50 dark:bg-neutral-800/50 text-neutral-700 dark:text-neutral-300 hover:border-primary-500 hover:text-primary-600 dark:hover:text-primary-400 transition-colors">
            <Filter className="h-5 w-5" />
            <span>Filtrer</span>
          </button>
          <button className="flex items-center space-x-2 px-4 py-2.5 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-medium hover:from-primary-600 hover:to-secondary-600 transition-all duration-300 hover:shadow-lg hover:shadow-primary-500/25">
            <Plus className="h-5 w-5" />
            <span>Nouveau produit</span>
          </button>
        </div>
      </div>

      <ProductsGrid />
    </>
  );
};

export default ProductsPage;
